import { useEffect } from 'react';

interface UsePopupWindowOptions {
  enabled?: boolean;
  phase?: string;
  onDisable?: () => void;
}

export const usePopupWindow = (options: UsePopupWindowOptions = {}) => {
  const { enabled = true, phase = '', onDisable } = options;

  useEffect(() => {
    console.log('🔍 Popup hook triggered - enabled:', enabled, 'phase:', phase);
    
    if (!enabled || !phase) {
      console.log('❌ Popup hook disabled or no phase');
      return;
    }

    // Check if this is already a popup window
    const isPopupWindow = () => {
      console.log('🔍 Checking if window is popup...');
      console.log('Window opener:', window.opener);
      console.log('Window name:', window.name);
      console.log('Window inner width:', window.innerWidth);
      console.log('Window inner height:', window.innerHeight);
      console.log('Screen width:', window.screen.width);
      console.log('Screen height:', window.screen.height);
      console.log('Window screenX:', window.screenX);
      console.log('Window screenY:', window.screenY);
      
      // Check if window was opened by window.open()
      if (window.opener && window.opener !== window) {
        console.log('✅ Detected: Window has opener (popup)');
        return true;
      }
      
      // Check if window has specific popup characteristics
      if (window.name && window.name.includes('scareware')) {
        console.log('✅ Detected: Window name contains scareware (popup)');
        return true;
      }
      
      // Check if window is significantly smaller than screen (more reliable popup detection)
      const widthRatio = window.innerWidth / window.screen.width;
      const heightRatio = window.innerHeight / window.screen.height;
      console.log('📏 Window size ratios - width:', widthRatio.toFixed(2), 'height:', heightRatio.toFixed(2));
      
      // Only consider it a popup if it's very small (less than 50% of screen)
      if (widthRatio < 0.5 || heightRatio < 0.5) {
        console.log('✅ Detected: Window significantly smaller than screen (popup)');
        return true;
      }
      
      // Check if window is positioned at 0,0 (fullscreen popup behavior)
      if (window.screenX === 0 && window.screenY === 0) {
        console.log('✅ Detected: Window at 0,0 position (popup)');
        return true;
      }
      
      console.log('❌ Not detected as popup window');
      return false;
    };

    // Only spawn popup if we're not already in one
    if (!isPopupWindow()) {
      console.log('🚀 Attempting to create popup window...');
      
      // Real scareware technique: Open new window in fullscreen
      const openFullscreenPopup = () => {
        try {
          var params = [
            'height=' + window.screen.height,
            'width=' + window.screen.width,
            'fullscreen=yes' // only works in IE, but here for completeness
          ].join(',');
          
          console.log('📋 Popup params:', params);
          console.log('🎯 Opening popup to URL:', `/${phase}`);
          
          // Real scareware technique: Use window.open with fullscreen features
          const popup = window.open(
            `/${phase}`, // Navigate to the same phase
            `scareware_${phase}_${Date.now()}`, // Unique window name
            params
          );
          
          console.log('📱 Popup result:', popup);
          
          if (popup) {
            console.log('✅ Popup created successfully!');
            // Real scareware technique: Move to 0,0 and focus the popup
            popup.moveTo(0, 0);
            popup.focus();
            
            // Monitor the popup window for closure (only if popup was successfully created)
            const monitorPopup = () => {
              try {
                // Check if popup is closed
                if (popup.closed) {
                  console.log('🚨 Popup was closed - spawning new one...');
                  // Real scareware technique: Spawn new popup when one is closed
                  setTimeout(() => {
                    openFullscreenPopup();
                  }, 1000); // 1 second delay before spawning new popup
                  return;
                }
                
                // Continue monitoring
                setTimeout(monitorPopup, 500); // Check every 500ms
              } catch (error) {
                console.log('⚠️ Error monitoring popup:', error);
                // If we can't access popup, it might be closed - spawn new one
                setTimeout(() => {
                  openFullscreenPopup();
                }, 1000);
              }
            };
            
            // Start monitoring the popup (only if popup exists)
            setTimeout(monitorPopup, 1000); // Start monitoring after 1 second
            
            // Close the original window after a short delay
            setTimeout(() => {
              try {
                console.log('🔒 Closing original window...');
                window.close();
              } catch (error) {
                console.log('⚠️ Could not close original window:', error);
              }
            }, 500);
          } else {
            console.log('❌ Popup was blocked - trying fallback...');
            // Popup was blocked - try alternative approach
            try {
              // Try to resize current window to fullscreen
              window.resizeTo(window.screen.width, window.screen.height);
              window.moveTo(0, 0);
              console.log('🔄 Fallback: Resized current window');
            } catch (error) {
              console.log('⚠️ Fallback failed:', error);
            }
          }
        } catch (error) {
          console.log('💥 Error creating popup:', error);
        }
      };

      // Small delay to ensure page is loaded
      const timer = setTimeout(openFullscreenPopup, 100);
      console.log('⏰ Set timer for popup creation (100ms delay)');
      
      return () => {
        console.log('🧹 Cleaning up popup timer');
        clearTimeout(timer);
      };
    } else {
      console.log('✅ Already in popup window - no action needed');
    }
  }, [enabled, phase]);
};
